mapper.select:
select DISTINCT FIN_PRODUCT.FINPROD_MARKET_ID id, NVL(p.FINPROD_ABBR,FIN_PRODUCT.FINPROD_ABBR) text, NVL(p.FINPROD_ID,FIN_PRODUCT.FINPROD_ID) object,
DECODE(FIN_PRODUCT_ADD.DEAL_MODE,#{dealMode_10,jdbcType=VARCHAR},#{yeOrNO_N,jdbcType=VARCHAR},fin_product_add.IS_LAY) col from FIN_CASH_PAY_RULE, FIN_CASH_INFO, FIN_PRODUCT INNER JOIN PTL_MANAGE_OBJ ON (PTL_MANAGE_OBJ.MANAGE_OBJ_ID = FIN_PRODUCT.FINPROD_ID or PTL_MANAGE_OBJ.MANAGE_OBJ_ID= FIN_PRODUCT.P_FINPROD_ID) INNER JOIN FIN_PRODUCT_ADD D2 ON FIN_PRODUCT.FINPROD_ID = D2.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
LEFT JOIN FIN_PRODUCT P ON FIN_PRODUCT.P_FINPROD_ID = P.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT_ADD.FINPROD_ID = P.FINPROD_ID and P.PROFIT_TYPE = #{PROFIT_TYPE_01} where FIN_PRODUCT.FINPROD_ID = FIN_CASH_PAY_RULE.FINPROD_ID AND FIN_CASH_PAY_RULE.PAY_CYCLE != #{payCycle,jdbcType=VARCHAR} AND FIN_PRODUCT.FINPROD_TYPE = #{finprodType2,jdbcType=VARCHAR} AND FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID AND FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
AND (FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) OR FIN_PRODUCT.FINPROD_ABBR like concat('%',concat(#{search},'%')) OR FIN_PRODUCT.P_FINPROD_ID like concat('%',concat(#{search},'%') ) )
AND FIN_PRODUCT.FINPROD_MARKET_ID = #{initValue}
AND ((FIN_PRODUCT.PROFIT_TYPE != #{PROFIT_TYPE_02} and ((P.FINPROD_ID IS NOT NULL and D2.deal_mode != #{dealMode_01,jdbcType=VARCHAR}) or D2.deal_mode = #{dealMode_01,jdbcType=VARCHAR})) OR FIN_PRODUCT.PROFIT_TYPE = #{PROFIT_TYPE_02})

select FIN_CASH_INFO.CASH_ID id, MST_FEEINFO.FEE_NAME text
from FIN_CASH_INFO, MST_FEEINFO, FIN_PRODUCT left join PRD_LAYER_PARAM on FIN_PRODUCT.FINPROD_ID = PRD_LAYER_PARAM.FINPROD_ID where FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND FIN_CASH_INFO.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR} AND FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR}
AND FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID
AND FIN_PRODUCT.FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR}
AND FIN_CASH_INFO.CASH_ID = #{initValue,jdbcType=VARCHAR}
and PRD_LAYER_PARAM.PROD_STYLE = #{prodType}
AND EXISTS (SELECT 1 FROM FIN_CASH_PLAN WHERE FIN_CASH_INFO.CASH_ID = FIN_CASH_PLAN.CASH_ID)

select a.prodType,a.VDATE,a.MDATE,a.PAY_DATE,a.PAY_STATUS,a.finprodId from( select plp.prod_style prodType, FIN_CASH_PLAN.VDATE VDATE, FIN_CASH_PLAN.MDATE MDATE, FIN_CASH_PLAN.PAY_DATE PAY_DATE, CASE WHEN TRD_PRODUCT_DEAL.TRADE_ID IS NOT NULL THEN '已支付' WHEN BOK_POSITION_PRDFEE.FINPROD_ID IS NOT NULL AND (BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP IS NULL OR BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP= 0) THEN '无需支付' ELSE '未支付' end PAY_STATUS,
FIN_CASH_PLAN.FINPROD_ID finprodId
from FIN_CASH_PLAN INNER JOIN FIN_CASH_INFO ON FIN_CASH_INFO.CASH_ID = FIN_CASH_PLAN.CASH_ID left join TRD_PRODUCT_DEAL on FIN_CASH_PLAN.CASH_ID = TRD_PRODUCT_DEAL.CASH_ID AND FIN_CASH_PLAN.MDATE = TRD_PRODUCT_DEAL.MDATE AND TRD_PRODUCT_DEAL.PS = #{ps,jdbcType=VARCHAR} AND TRD_PRODUCT_DEAL.IS_CANCEL != 'Y' AND (TRD_PRODUCT_DEAL.TRADE_STATUS IS NULL OR TRD_PRODUCT_DEAL.TRADE_STATUS ='01') left join prd_layer_param plp on FIN_CASH_PLAN.Finprod_Id = plp.Finprod_Id LEFT JOIN ( SELECT FIN_CASH_PLAN.CASH_ID, FIN_CASH_PLAN.PAY_DATE, MAX(FIN_FLOAT_ACCRUAL_SCHE.VAL_DATE) VAL_DATE FROM FIN_CASH_PLAN INNER JOIN FIN_FLOAT_ACCRUAL_SCHE ON FIN_FLOAT_ACCRUAL_SCHE.CASH_ID = FIN_CASH_PLAN.CASH_ID AND FIN_FLOAT_ACCRUAL_SCHE.VAL_DATE < FIN_CASH_PLAN.PAY_DATE GROUP BY FIN_CASH_PLAN.CASH_ID,FIN_CASH_PLAN.PAY_DATE ) ACCRUAL_SCHE ON ACCRUAL_SCHE.CASH_ID = FIN_CASH_PLAN.CASH_ID AND ACCRUAL_SCHE.PAY_DATE = FIN_CASH_PLAN.PAY_DATE LEFT JOIN BOK_POSITION_PRDFEE ON BOK_POSITION_PRDFEE.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID AND BOK_POSITION_PRDFEE.FEE_TYPE = FIN_CASH_INFO.CASH_TYPE_2 AND BOK_POSITION_PRDFEE.BRANCH = FIN_CASH_INFO.BRANCH AND BOK_POSITION_PRDFEE.CDATE = ACCRUAL_SCHE.VAL_DATE where FIN_CASH_PLAN.CASH_ID = #{cashId,jdbcType=VARCHAR}
and plp.prod_style=#{prodType,jdbcType=VARCHAR}
)a group by a.prodType,a.VDATE,a.MDATE,a.PAY_DATE,a.PAY_STATUS,a.finprodId order by a.VDATE ASC

select FIN_PRODUCT.FINPROD_MARKET_ID id, FIN_PRODUCT.FINPROD_ABBR text, FIN_PRODUCT.FINPROD_ID || ',' || to_char(FIN_PRODUCT.VDATE,'yyyy-mm-dd') || ',' || to_char(FIN_PRODUCT.MDATE,'yyyy-mm-dd') || ',' || FIN_PRODUCT.PROFIT_TYPE || ',' || FIN_PRODUCT.CALENDAR_ID || ',' || to_char(FIN_PRODUCT.LIQUIDATION_DATE,'yyyy-mm-dd') object,
case when FIN_PRODUCT.PROFIT_TYPE = #{profitType_02} then #{YES_OR_NO_N} when FIN_PRODUCT_ADD.DEAL_MODE = #{dealMode_10} then #{YES_OR_NO_N} else FIN_PRODUCT_ADD.IS_LAY end as col /* 多级法人改造 add by caojin 2020/6/20 start */ ,FIN_PRODUCT.FINPROD_ID finprodId /* 多级法人改造 add by caojin 2020/6/20 end */
from FIN_PRODUCT INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = FIN_PRODUCT.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
INNER JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID AND FIN_PRODUCT_ADD.ISSUE_STATUS = #{ISSUE_STATUS_01}
FIN_PRODUCT.FINPROD_TYPE2 = #{args0,jdbcType=VARCHAR}
AND (FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) OR FIN_PRODUCT.FINPROD_ABBR like concat('%',concat(#{search,jdbcType=VARCHAR},'%')))
AND FIN_PRODUCT.FINPROD_MARKET_ID = #{initValue}

SELECT distinct PRD_LAYER_PARAM.PROD_STYLE text, FIN_PRODUCT.FINPROD_ID id, FIN_PRODUCT.FINPROD_ID || ',' || to_char(FIN_PRODUCT.VDATE,'yyyy-mm-dd') || ',' || to_char(FIN_PRODUCT.MDATE,'yyyy-mm-dd') || ',' || FIN_PRODUCT.PROFIT_TYPE || ',' || FIN_PRODUCT.CALENDAR_ID || ',' || to_char(FIN_PRODUCT.LIQUIDATION_DATE,'yyyy-mm-dd') object FROM PRD_LAYER_PARAM,FIN_CASH_INFO,FIN_PRODUCT WHERE PRD_LAYER_PARAM.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID AND FIN_CASH_INFO.CASH_TYPE_1 =#{cashType1_03} AND PRD_LAYER_PARAM.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
AND PRD_LAYER_PARAM.P_FINPROD_ID = #{pfinprodId}
AND (FIN_PRODUCT.FINPROD_ABBR like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) OR PRD_LAYER_PARAM.PROD_STYLE like concat('%',concat(#{search,jdbcType=VARCHAR},'%')))
AND PRD_LAYER_PARAM.FINPROD_ID = #{initValue}

mapper.delete:
delete from FIN_CASH_PAY_RULE
where CASH_ID = #{cashId,jdbcType=VARCHAR}
  and EFF_DATE >= #{effDate,jdbcType=DATE}

delete from FIN_CASH_CALC_RULE
where CASH_ID = #{cashId,jdbcType=VARCHAR}
  and EFF_DATE >= #{effDate,jdbcType=DATE}

delete from FIN_FLOAT_COUNTING_RULE
where CASH_ID = #{cashId,jdbcType=VARCHAR}
  and EFF_DATE >= #{effDate,jdbcType=DATE}

delete from FIN_RATE_INFO
where CASH_ID = #{cashId,jdbcType=VARCHAR}
  and EFF_DATE >= #{effDate,jdbcType=DATE}
